use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-g2-index-gather";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let old="/tmp/zopro-g2-prefix-tree";let text=serde_json::to_string(&read(format!("{old}/native-plan.json"))).unwrap().replace(old,R).replace("--cfg zopro_g2_prefix_tree","--cfg zopro_g2_prefix_tree --cfg zopro_g2_index_gather");let mut plan:Value=serde_json::from_str(&text).unwrap();
 for step in plan["steps"].as_array_mut().unwrap(){if step["name"]=="on-core"{let tests=step["required_tests"].as_array_mut().unwrap();for t in ["msm::g2_gather::tests::signed_gather_groups_cover_exceptions_odd_tails_and_skew","msm::g2_gather::tests::compact_buffer_and_typed_forecasts_cover_boundaries","msm_affine::g2_index_gather::tests::gather_query_complete_curve_generator_oracles","msm_affine::g2_index_gather::tests::actual_size_gather_matches_stream_and_generator","msm_affine::g2_index_gather::tests::gather_forecast_and_geometry_are_checked"]{tests.push(json!(t));}}}
 let manifest=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=BTreeMap::new();let mut changed=Vec::new();
 for(rel,h)in manifest["source_files_sha256"].as_object().unwrap(){let p=r.join("candidate").join(rel);let actual=hash(&p);if actual!=h.as_str().unwrap(){changed.push(rel.clone());}pins.insert(p.display().to_string(),actual);assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel)),h.as_str().unwrap());}assert_eq!(changed.len(),5);
 for rel in ["candidate/crates/zopro-core/src/msm_affine/g2_level_tree.rs","candidate/crates/zopro-core/src/msm_affine/g2_prefix_tree.rs"]{assert_eq!(hash(r.join(rel)),hash(Path::new(old).join(rel)));}
 for rel in ["candidate/crates/zopro-core/src/msm_affine/g2_level_tree.rs","candidate/crates/zopro-core/src/msm_affine/g2_prefix_tree.rs","candidate/crates/zopro-core/src/msm_affine/g2_index_gather.rs","candidate/crates/zopro-core/src/msm/g2_gather.rs","adapt.rs","probe.rs","support/perf.rs","design.md","setup.rs","run.rs","closeout.rs","cases.json"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(&p));}
 for c in read(r.join("cases.json")).as_array().unwrap(){for key in ["key","image","request"]{let p=c[key].as_str().unwrap();pins.insert(p.into(),hash(p));}}
 save(r.join("source-pins.json"),&json!(pins));save(r.join("source-audit.json"),&json!({"changed_originals":changed,"new_modules":["msm/g2_gather.rs","msm_affine/g2_index_gather.rs"],"inherited_modules":["msm_affine/g2_level_tree.rs","msm_affine/g2_prefix_tree.rs"],"original_sources":170,"production_unchanged":true,"SDK_dispatch_unchanged":true,"unchanged_old_components":true}));save(r.join("native-plan.json"),&plan);
}
